export default function calcWorkdays(input) {
  const { start, end, holidays = [], leaveType } = input;
  if (!start || !end) return { days: 0, skipped: [], warnings: ["时间未填完整"] };
  const holidaySet = new Set((holidays || []).map(h => typeof h === "string" ? h : h.date));
  const oneDay = 86400000;
  const from = new Date(start); const to = new Date(end);
  if (to < from) return { days: 0, skipped: [], warnings: ["结束时间早于开始时间"] };
  let days = 0; const skipped = [];
  for (let t = from.getTime(); t <= to.getTime(); t += oneDay) {
    const d = new Date(t); const iso = d.toISOString().slice(0, 10);
    const weekend = d.getUTCDay() === 0 || d.getUTCDay() === 6;
    if (holidaySet.has(iso)) { skipped.push(iso); continue; }
    if (weekend) { skipped.push(iso); continue; }
    days += 1;
  }
  const warnings = [];
  if (leaveType === "annual" && days > 15) warnings.push("年假超过 15 天需院长审批");
  return { days, skipped, warnings };
}
